/**
 * withPodsDeploymentTarget — Expo config plugin (japa#208).
 *
 * Xcode 27 refuses to build any pod target whose IPHONEOS_DEPLOYMENT_TARGET
 * is below iOS 15 ("the range of supported deployment target versions is
 * 15.0 to 27.x"). Several pods still declare 9.0 / 12.x for their resource
 * bundle targets (GoogleUtilities_Privacy, nanopb, PromisesSwift,
 * RNCAsyncStorage resources, RNSVGFilters, ...).
 *
 * `ios/` is generated by prebuild (CNG) and gitignored, so the fix can't live
 * in a committed Podfile. This plugin appends a step to the generated
 * Podfile's `post_install` hook that raises every pod target below
 * MIN_TARGET to MIN_TARGET. Pods that already target a newer iOS keep theirs.
 */
// Config plugins run in Node as CommonJS (app.json loads them by path), so
// require() is the supported form here.
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { withPodfile } = require('expo/config-plugins');

// The app's own minimum (expo SDK 56 default). Kept as a constant so the
// Podfile step and this comment can't drift apart.
const MIN_TARGET = '15.1';

// Marker so running prebuild twice never inserts the block twice.
const MARKER = '# seli: withPodsDeploymentTarget';

// Ruby inserted at the top of `post_install do |installer|`.
const RUBY = `    ${MARKER} (japa#208)
    installer.pods_project.targets.each do |t|
      t.build_configurations.each do |c|
        v = c.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        c.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${MIN_TARGET}' if v.nil? || v.to_f < ${MIN_TARGET}
      end
    end
`;

module.exports = function withPodsDeploymentTarget(config) {
  return withPodfile(config, (cfg) => {
    const src = cfg.modResults.contents;
    // Already applied (idempotent prebuild).
    if (src.includes(MARKER)) return cfg;
    const hook = 'post_install do |installer|\n';
    // Fail loudly rather than silently ship a build that won't compile.
    if (!src.includes(hook)) {
      throw new Error(
        'withPodsDeploymentTarget: no `post_install do |installer|` in Podfile',
      );
    }
    cfg.modResults.contents = src.replace(hook, hook + RUBY);
    return cfg;
  });
};
